from PIL import Image
for f in ['/home/robot/captures/overview_003.jpg','/home/robot/captures/carton_004.jpg']:
    im=Image.open(f).convert('L').resize((80,30))
    chars='@%#*+=-:. '
    print('\n---',f,'---')
    for y in range(im.height):
        line=''
        for x in range(im.width):
            v=im.getpixel((x,y))
            line+=chars[v*(len(chars)-1)//255]
        print(line.rstrip())
PY"}

